<template><div class="flex min-h-[calc(100dvh-130px)] flex-col p-4"><div class="m-card flex flex-1 flex-col"><h1 class="text-sm font-bold text-slate-800">{{ thread?.subject || 'Order conversation' }}</h1><div class="flex-1 space-y-2 py-4"><div v-for="item in items" :key="item.id" class="rounded-xl bg-slate-50 p-3"><p class="text-[10px] uppercase text-slate-400">{{ item.sender_role }}</p><p class="mt-1 text-sm text-slate-700">{{ item.body }}</p></div></div><form class="flex gap-2 border-t border-slate-100 pt-3" @submit.prevent="send"><input v-model.trim="body" required class="m-input" placeholder="Write a message" /><button class="rounded-xl bg-indigo-500 px-4 text-sm font-semibold text-white">Send</button></form></div><p v-if="error" class="mt-3 text-sm text-red-600">{{ error }}</p></div></template>
<script setup lang="ts">
definePageMeta({ middleware: ['auth'] }); const route = useRoute(); const api = useCommerce(); const thread = ref<any>(); const items = ref<any[]>([]); const body = ref(''); const error = ref(''); async function load() { thread.value = await api.getOrderThread(String(route.params.order_id)); items.value = (await api.listMessages(thread.value.id)).items } async function send() { try { await api.postMessage(thread.value.id, body.value); body.value = ''; await load() } catch (e: any) { error.value = e?.data?.detail || e?.message } } onMounted(async () => { try { await load() } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
